import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.Y8If66rx.js";const m=JSON.parse('{"title":"Migration from application-owned tables","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration.md","filePath":"guide/migration.md"}'),n={name:"guide/migration.md"};function r(l,e,s,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="migration-from-application-owned-tables" tabindex="-1">Migration from application-owned tables <a class="header-anchor" href="#migration-from-application-owned-tables" aria-label="Permalink to &quot;Migration from application-owned tables&quot;">​</a></h1><p>Use this guide when moving the shared rendering and interaction behavior out of a consuming application and into <code>@busmap/table</code>. The package should remain an independent UI capability: do not move application data access or domain rules into it.</p><h2 id="_1-separate-responsibilities" tabindex="-1">1. Separate responsibilities <a class="header-anchor" href="#_1-separate-responsibilities" aria-label="Permalink to &quot;1. Separate responsibilities&quot;">​</a></h2><p>Keep these concerns in the consuming application:</p><ul><li>Fetching, transport clients, DataSources, Redux state, and subscriptions.</li><li>Domain filtering, authorization, labels, and row projection.</li><li>Selection state, application actions, and feature/module lifecycle.</li><li>Decisions about which columns a particular screen shows.</li></ul><p>Move only reusable table presentation and behavior into the package:</p><ul><li>Rendering and table primitives.</li><li>Pixel/percentage column sizing and resize separators.</li><li>The included client-side sorting feature and its controls.</li><li>Optional measured row virtualization.</li></ul><p>The package takes prepared rows and typed column definitions as inputs. It does not own a domain model, application store, API client, or theme provider.</p><h2 id="_2-add-the-package-and-stylesheet" tabindex="-1">2. Add the package and stylesheet <a class="header-anchor" href="#_2-add-the-package-and-stylesheet" aria-label="Permalink to &quot;2. Add the package and stylesheet&quot;">​</a></h2><p>Resolve the React peer version and package registry first; see <a href="./getting-started.html">Getting started</a>. Import <code>@busmap/table/style.css</code> once from the application entry.</p><h2 id="_3-replace-the-renderer-incrementally" tabindex="-1">3. Replace the renderer incrementally <a class="header-anchor" href="#_3-replace-the-renderer-incrementally" aria-label="Permalink to &quot;3. Replace the renderer incrementally&quot;">​</a></h2><p>Create columns with <code>createColumnHelper</code>, initialize the table with <code>useResizableTable</code>, then replace the application-owned table renderer with <code>ResizableTable</code>. Add <code>TableSortControls</code> only if that screen needs the provided client-side sort UI. Enable <code>virtualize</code> only when justified by the screen&#39;s row count and measured performance.</p><p>Keep existing row projection and action callbacks in the module. If a custom table rendering pattern is needed, use the exported <code>Table</code> primitives and keep its data mapping in the application.</p><h2 id="_4-retire-compatibility-paths-deliberately" tabindex="-1">4. Retire compatibility paths deliberately <a class="header-anchor" href="#_4-retire-compatibility-paths-deliberately" aria-label="Permalink to &quot;4. Retire compatibility paths deliberately&quot;">​</a></h2><p>The original Bus Map application retained <code>Table</code>, <code>ResizableTable</code>, <code>resizableTableFeatures</code>, <code>TableSortControls</code>, <code>SortOrder</code>, and <code>resizeColumnPair</code> re-exports through <code>@busmap/design-system</code> during the extraction. Those exports belong to that application&#39;s compatibility layer; they are not part of this package and are not required to consume it.</p><p>For independent consumers, import directly from <code>@busmap/table</code>. For the original app, update imports a feature at a time and remove the design-system aliases only after all consumers have moved. Avoid maintaining duplicate implementations or introducing a reverse dependency from the table package to the design system.</p><h2 id="_5-validate-at-both-boundaries" tabindex="-1">5. Validate at both boundaries <a class="header-anchor" href="#_5-validate-at-both-boundaries" aria-label="Permalink to &quot;5. Validate at both boundaries&quot;">​</a></h2><ul><li>Unit-test application selectors or mapping functions with domain fixtures.</li><li>Test the table component for rendered data, sorting, resize keyboard interaction, and any row callbacks it supplies.</li><li>Type-check the consuming workspace and build the application.</li><li>Check the production CSS bundle includes <code>@busmap/table/style.css</code>.</li></ul><p>Run <code>npm test</code> for sizing calculations, <code>npm run lint</code>, and <code>npm run build</code>. Keep consumer-specific integration tests in the consumer repository. Review <a href="./column-sizing.html#input-and-compatibility">sizing compatibility changes</a> when migrating old adjacent-pair resize behavior.</p>',19)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
